"""Dynamic DFS forest maintenance (directed, root 0).

Strategy: maintain a genuine DFS forest of the current graph.  On each
update, check whether the current forest is still a valid DFS forest of
the new graph (Lemma 1: a spanning tree is a DFS tree iff it has no
forward-cross edges, plus the forest must span exactly the reachable set).
If it is valid, keep it (fast path).  If not, recompute the DFS forest
from scratch (correctness first).
"""


def _dfs(graph, n):
    """Iterative DFS from root 0. Returns (parent, discover, finish)."""
    parent = [None] * n
    discover = [-1] * n
    finish = [-1] * n
    time = [0]
    # stack of (vertex, next_child_index)
    stack = []
    discover[0] = 0
    time[0] = 1
    stack.append((0, 0))
    while stack:
        u, ci = stack[-1]
        advanced = False
        row = graph[u]
        while ci < n:
            v = ci
            ci += 1
            if row[v] and discover[v] == -1:
                parent[v] = u
                discover[v] = time[0]
                time[0] += 1
                stack[-1] = (u, ci)
                stack.append((v, 0))
                advanced = True
                break
        if not advanced:
            finish[u] = time[0]
            time[0] += 1
            stack.pop()
    return parent, discover, finish


def _is_valid(graph, parent, discover, finish, n):
    """Check the forest is a DFS forest of graph (no forward-cross edges)."""
    for u in range(n):
        if discover[u] == -1:
            continue
        row = graph[u]
        for v in range(n):
            if not row[v]:
                continue
            if discover[v] == -1:
                # edge to unreachable vertex: fine (v not in forest)
                continue
            if discover[u] < discover[v]:
                # v must be a descendant of u
                if not (discover[u] < discover[v] < finish[v] < finish[u]):
                    return False
    # parent pointers must be actual edges of the current graph
    for v in range(n):
        if discover[v] != -1 and v != 0:
            p = parent[v]
            if p is None or not graph[p][v]:
                return False
    # spanning check: reachable set in graph must equal forest vertex set
    seen = [False] * n
    stack = [0]
    seen[0] = True
    while stack:
        u = stack.pop()
        for v in range(n):
            if graph[u][v] and not seen[v]:
                seen[v] = True
                stack.append(v)
    for v in range(n):
        if seen[v] != (discover[v] != -1):
            return False
    return True


def init(graph):
    n = len(graph)
    parent, discover, finish = _dfs(graph, n)
    return {
        'parent': parent,
        'discover': discover,
        'finish': finish,
        'n': n,
    }


def _maybe_recompute(graph, state):
    n = state['n']
    parent = state['parent']
    discover = state['discover']
    finish = state['finish']
    if _is_valid(graph, parent, discover, finish, n):
        return state
    parent, discover, finish = _dfs(graph, n)
    return {
        'parent': parent,
        'discover': discover,
        'finish': finish,
        'n': n,
    }


def insert_edge(graph, edge, state):
    return _maybe_recompute(graph, state)


def delete_edge(graph, edge, state):
    return _maybe_recompute(graph, state)

"""Dynamic DFS forest from a fixed root (vertex 0) under edge insert/delete.

Strategy: maintain a genuine DFS forest (parent, discover, finish) of the
current graph.  On an update, check whether the current forest is still a
valid DFS forest of the new graph (Lemma 1: a spanning search tree is a DFS
tree iff it has no forward-cross edges).  If it is valid, keep it.  If not,
recompute the DFS from scratch (correct fallback).

This is correct for every update; the fast path avoids recomputation whenever
the old forest remains a valid DFS forest of the updated graph.
"""


def _dfs_from(graph, root):
    """Iterative DFS from root; returns (parent, discover, finish)."""
    n = len(graph)
    parent = [None] * n
    discover = [-1] * n
    finish = [-1] * n
    t = 0
    # stack of [vertex, next_child_index]
    stack = [[root, 0]]
    discover[root] = t
    t += 1
    while stack:
        u, i = stack[-1]
        advanced = False
        while i < n:
            if graph[u][i] and discover[i] == -1:
                parent[i] = u
                discover[i] = t
                t += 1
                stack[-1][1] = i + 1
                stack.append([i, 0])
                advanced = True
                break
            i += 1
        if not advanced:
            finish[u] = t
            t += 1
            stack.pop()
    return parent, discover, finish


def _is_valid_dfs(graph, parent, discover, finish):
    """Check the forest is a valid DFS forest of graph.

    Conditions:
    1. parent pointers form a tree over reachable vertices, consistent with
       discover/finish (parent discovered before child, child interval inside
       parent interval), and every parent edge exists in the current graph.
    2. No forward-cross edge: for every edge u->v with discover[u] <
       discover[v], v must be a descendant of u.
    """
    n = len(graph)
    for u in range(n):
        du = discover[u]
        if du == -1:
            continue
        for v in range(n):
            if not graph[u][v]:
                continue
            dv = discover[v]
            if dv == -1:
                # edge to unreachable vertex: u reachable, v not -> v should
                # be reachable. Invalid.
                return False
            if du < dv:
                # v discovered after u: v must be a descendant of u
                if not (dv < finish[v] and finish[v] < finish[u]):
                    return False
    # verify parent consistency
    for v in range(n):
        if discover[v] == -1:
            if parent[v] is not None:
                return False
            continue
        p = parent[v]
        if p is None:
            # root of a tree; must be the source root 0
            if v != 0:
                return False
            continue
        if not graph[p][v]:
            return False
        if discover[p] >= discover[v]:
            return False
        if not (discover[v] < finish[v] and finish[v] < finish[p]):
            return False
    return True


def _make_state(graph):
    parent, discover, finish = _dfs_from(graph, 0)
    return {'parent': parent, 'discover': discover, 'finish': finish}


def init(graph):
    return _make_state(graph)


def insert_edge(graph, edge, state):
    parent, discover, finish = state['parent'], state['discover'], state['finish']
    if _is_valid_dfs(graph, parent, discover, finish):
        return state
    return _make_state(graph)


def delete_edge(graph, edge, state):
    parent, discover, finish = state['parent'], state['discover'], state['finish']
    if _is_valid_dfs(graph, parent, discover, finish):
        return state
    return _make_state(graph)

